package com.example.directory

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.util.*
import javax.naming.*
import javax.naming.directory.*

fun main() {
    embeddedServer(Netty, port = 8080) {
        module()
    }.start(wait = true)
}

fun Application.module() {
    val ldapHost = System.getenv("LDAP_HOST") ?: "ldap://localhost:389"
    val baseDn = System.getenv("LDAP_BASE_DN") ?: "dc=corp,dc=internal"
    val bindDn = System.getenv("LDAP_BIND_DN") ?: "cn=svc-app,ou=services,dc=corp,dc=internal"
    val bindPassword = System.getenv("LDAP_BIND_PASSWORD") ?: "changeme"

    routing {
        get("/api/v1/employees/search") {
            val query = call.request.queryParameters["q"]
            if (query.isNullOrBlank()) {
                call.respond(HttpStatusCode.BadRequest, mapOf("error" to "Missing query parameter 'q'"))
                return@get
            }

            val department = call.request.queryParameters["dept"] ?: "*"
            val results = searchDirectory(ldapHost, baseDn, bindDn, bindPassword, query, department)
            call.respond(HttpStatusCode.OK, results)
        }

        get("/api/v1/employees/{uid}") {
            val uid = call.parameters["uid"]
            if (uid.isNullOrBlank()) {
                call.respond(HttpStatusCode.BadRequest, mapOf("error" to "Missing uid"))
                return@get
            }

            val result = lookupEmployee(ldapHost, baseDn, bindDn, bindPassword, uid)
            if (result != null) {
                call.respond(HttpStatusCode.OK, result)
            } else {
                call.respond(HttpStatusCode.NotFound, mapOf("error" to "Employee not found"))
            }
        }

        get("/health") {
            call.respond(HttpStatusCode.OK, mapOf("status" to "healthy"))
        }
    }
}

fun searchDirectory(
    ldapHost: String, baseDn: String, bindDn: String, bindPassword: String,
    query: String, department: String
): List<Map<String, String>> {
    val env = Hashtable<String, String>()
    env[Context.INITIAL_CONTEXT_FACTORY] = "com.sun.jndi.ldap.LdapCtxFactory"
    env[Context.PROVIDER_URL] = ldapHost
    env[Context.SECURITY_AUTHENTICATION] = "simple"
    env[Context.SECURITY_PRINCIPAL] = bindDn
    env[Context.SECURITY_CREDENTIALS] = bindPassword

    // Build LDAP filter - combines user input with department filter
    val filter = "(&(objectClass=inetOrgPerson)(|(cn=$query)(mail=$query))(department=$department))"

    val ctx = InitialDirContext(env)
    val controls = SearchControls()
    controls.searchScope = SearchControls.SUBTREE_SCOPE
    controls.returningAttributes = arrayOf("cn", "mail", "uid", "department", "telephoneNumber")

    val results = mutableListOf<Map<String, String>>()
    try {
        val searchResults = ctx.search(baseDn, filter, controls)
        while (searchResults.hasMore()) {
            val entry = searchResults.next()
            val attrs = entry.attributes
            results.add(mapOf(
                "cn" to (attrs.get("cn")?.get()?.toString() ?: ""),
                "mail" to (attrs.get("mail")?.get()?.toString() ?: ""),
                "uid" to (attrs.get("uid")?.get()?.toString() ?: ""),
                "department" to (attrs.get("department")?.get()?.toString() ?: ""),
                "phone" to (attrs.get("telephoneNumber")?.get()?.toString() ?: "")
            ))
        }
    } finally {
        ctx.close()
    }
    return results
}

fun lookupEmployee(
    ldapHost: String, baseDn: String, bindDn: String, bindPassword: String,
    uid: String
): Map<String, String>? {
    val env = Hashtable<String, String>()
    env[Context.INITIAL_CONTEXT_FACTORY] = "com.sun.jndi.ldap.LdapCtxFactory"
    env[Context.PROVIDER_URL] = ldapHost
    env[Context.SECURITY_AUTHENTICATION] = "simple"
    env[Context.SECURITY_PRINCIPAL] = bindDn
    env[Context.SECURITY_CREDENTIALS] = bindPassword

    // Direct uid lookup - also unsanitized
    val filter = "(&(objectClass=inetOrgPerson)(uid=$uid))"

    val ctx = InitialDirContext(env)
    val controls = SearchControls()
    controls.searchScope = SearchControls.SUBTREE_SCOPE
    controls.returningAttributes = arrayOf("cn", "mail", "uid", "department", "telephoneNumber", "title", "manager")

    try {
        val searchResults = ctx.search(baseDn, filter, controls)
        if (searchResults.hasMore()) {
            val entry = searchResults.next()
            val attrs = entry.attributes
            return mapOf(
                "cn" to (attrs.get("cn")?.get()?.toString() ?: ""),
                "mail" to (attrs.get("mail")?.get()?.toString() ?: ""),
                "uid" to (attrs.get("uid")?.get()?.toString() ?: ""),
                "department" to (attrs.get("department")?.get()?.toString() ?: ""),
                "phone" to (attrs.get("telephoneNumber")?.get()?.toString() ?: ""),
                "title" to (attrs.get("title")?.get()?.toString() ?: ""),
                "manager" to (attrs.get("manager")?.get()?.toString() ?: "")
            )
        }
    } finally {
        ctx.close()
    }
    return null
}
